export function assertInRange(value: number, min: number, max: number): void {
  if (value < min || value > max) {
    throw new RangeError(`${value} is outside ${min}..${min}`)
  }
}

export function parsePort(raw: string): number {
  const port = Number(raw)
  if (!Number.isInteger(port)) throw new RangeError(`invalid port: ${raw}`)
  try {
    assertInRange(port, 1, 65535)
  } catch (err) {
    throw new RangeError(`invalid port: ${raw}`)
  }
  return port
}
